<?php $h=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$actor=(int)$_SESSION['user']['id']; ?>
<?php $archived=array_filter($orders,static function($o){return in_array($o['status'],['cancelled','refunded'],true);}); ?>
<div class="orders-tabs" role="tablist" aria-label="Order lists"><button type="button" role="tab" id="orders-live-tab" aria-controls="orders-live-panel" aria-selected="true" data-orders-tab="live">Online orders <span><?= count($orders)-count($archived) ?></span></button><button type="button" role="tab" id="orders-archive-tab" aria-controls="orders-archive-panel" aria-selected="false" tabindex="-1" data-orders-tab="archive">Cancelled &amp; refunded <span><?= count($archived) ?></span></button></div>
<div id="orders-live-panel" role="tabpanel" aria-labelledby="orders-live-tab">
<div class="orders-kanban" aria-label="Order status board">
<?php foreach(['pending'=>['New orders','Awaiting preparation'],'preparing'=>['Preparing','Being arranged with care'],'ready'=>['Ready','For pickup or delivery'],'completed'=>['Completed','Paid and fulfilled']] as $state=>$labels):$lane=array_filter($orders,static function($o)use($state){return $o['status']===$state;}); ?>
<section class="orders-column" data-order-status="<?= $state ?>" aria-label="<?= $labels[0] ?>"><header><div><span class="lane-dot"></span><h4><?= $labels[0] ?></h4><span class="lane-count"><?= count($lane) ?></span></div><p><?= $labels[1] ?></p></header><div class="orders-drop-area">
<?php foreach($lane as $o):$targets=OnlineOrder::board_targets($o,$actor); ?>
<article class="orders-card" data-order-id="<?= (int)$o['id'] ?>" data-tracking="<?= $h($o['tracking_number']) ?>" data-current-status="<?= $state ?>" data-targets="<?= $h(json_encode($targets)) ?>" draggable="<?= $targets?'true':'false' ?>">
<div class="orders-card-top"><span><?= $h(($o['fulfillment_type']??'pickup')==='delivery'?'Delivery':'Pickup') ?></span><?php if($targets): ?><button class="order-drag-handle" type="button" aria-label="Drag <?= $h($o['tracking_number']) ?> to the next status" title="Drag to move order"><i class="fa-solid fa-grip-vertical" aria-hidden="true"></i></button><?php endif; ?></div>
<a draggable="false" class="order-open" href="<?= url('?route=admin/online_orders&tracking='.rawurlencode($o['tracking_number'])) ?>"><small><?= $h($o['tracking_number']) ?></small><h5><?= $h($o['customer_name']) ?></h5><p><?= $h($o['branch_name']) ?> · <?= $h(date('M j, g:i A',strtotime($o['created_at']))) ?></p><div class="orders-card-bottom"><strong>₱<?= number_format((float)$o['total'],2) ?></strong><span class="payment-tag payment-<?= $h($o['payment_status']) ?>"><?= $h(ucfirst($o['payment_status'])) ?></span></div></a>
<?php if($state==='ready'&&$o['payment_status']!=='paid'): ?><small class="order-payment-hint">Record payment before completing.</small><?php endif; ?>
</article><?php endforeach; ?><p class="orders-empty" <?= $lane?'hidden':'' ?>>No orders here yet.<br><small>Orders appear here as they progress.</small></p></div></section><?php endforeach; ?></div>
</div><div id="orders-archive-panel" role="tabpanel" aria-labelledby="orders-archive-tab" hidden><div class="orders-archive"><h3>Cancelled &amp; refunded orders</h3><p>Past orders that were cancelled or refunded.</p><?php foreach($archived as $o): ?><a class="order-open archive-order" href="<?= url('?route=admin/online_orders&tracking='.rawurlencode($o['tracking_number'])) ?>"><div><strong><?= $h($o['customer_name']) ?></strong><small><?= $h($o['tracking_number']) ?> · <?= $h($o['branch_name']) ?></small></div><span><?= $h(ucfirst($o['status'])) ?></span></a><?php endforeach; ?><?php if(!$archived): ?><div class="orders-empty">No cancelled or refunded orders yet.</div><?php endif; ?></div></div>
